DG = '^\\circ'
def A(x): return M(f'{x:g}{DG}')
def Wd(ans, cand, k=3):
    out = []
    for c in cand:
        if c != ans and c not in out and 0 < c < 360: out.append(c)
    t = 5
    while len(out) < k:
        c = ans + t * (1 if (t // 5) % 2 else -1); t += 5
        if c != ans and c not in out and 0 < c < 360: out.append(c)
    return [A(v) for v in out[:k]]
